#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef ssize_t (*readlink_fn)(const char *, char *, size_t);

ssize_t readlink(const char *path, char *buf, size_t size) {
  const char *replacement = getenv("LEAN_REAL_EXE");
  if (replacement && strcmp(path, "/proc/self/exe") == 0) {
    size_t length = strlen(replacement);
    if (length > size) length = size;
    memcpy(buf, replacement, length);
    return (ssize_t)length;
  }
  static readlink_fn original = 0;
  if (!original) original = (readlink_fn)dlsym(RTLD_NEXT, "readlink");
  return original(path, buf, size);
}

